@namespace sv_7bc200cb14b4482fbfb4943f2db0c4c1.Components.Pages.Settings
@using sv_7bc200cb14b4482fbfb4943f2db0c4c1.Services
@inject ISettingsService SettingsService

<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center"
         style="cursor:pointer" @onclick="ToggleExpanded">
        <span>Change Password</span>
        <span>@(_expanded ? "▲" : "▼")</span>
    </div>
    @if (_expanded)
    {
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="_currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="_newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="_confirmPassword" />
            </div>

            @if (!string.IsNullOrEmpty(_error))
            {
                <div class="alert alert-danger">@_error</div>
            }
            @if (_showSuccess)
            {
                <div class="alert alert-success">Password updated successfully!</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePasswordAsync" disabled="@_saving">
                @if (_saving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    private bool _expanded;
    private bool _saving;
    private bool _showSuccess;
    private string _error = "";
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";

    private void ToggleExpanded() => _expanded = !_expanded;

    private async Task UpdatePasswordAsync()
    {
        _error = "";
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _error = "New password cannot be empty.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _error = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

