@page "/settings"
@namespace sv_7bc200cb14b4482fbfb4943f2db0c4c1.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <div class="row g-0">
        <div class="col-md-3 col-lg-2">
            <SettingsSidebar ActiveSection="@_activeSection"
                            OnSectionChanged="section => _activeSection = section" />
        </div>
        <div class="col-md-9 col-lg-10">
            <div class="settings-content p-4">
                @switch (_activeSection)
                {
                    case "Profile":
                        <ProfileSection />
                        break;
                    case "Notifications":
                        <NotificationsSection />
                        break;
                    case "Security":
                        <SecuritySection />
                        break;
                    case "Appearance":
                        <AppearanceSection />
                        break;
                }
            </div>
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";
}

.settings-dashboard {
    min-height: calc(100vh - 100px);
}

::deep .settings-sidebar {
    background-color: #f8f9fa;
    min-height: calc(100vh - 100px);
    border-right: 1px solid #dee2e6;
    padding-top: 1rem;
}

::deep .settings-sidebar .nav-link {
    color: #495057;
    border: none;
    border-radius: 0;
    padding: 0.75rem 1.25rem;
    text-align: left;
    width: 100%;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: background-color 0.15s;
}

::deep .settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
}

::deep .settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: white;
    font-weight: 500;
}

::deep .settings-content {
    background-color: #fff;
    min-height: calc(100vh - 100px);
}

::deep .settings-section h3 {
    margin-bottom: 1.5rem;
    padding-bottom: 0.75rem;
    border-bottom: 1px solid #dee2e6;
}

::deep .appearance-preview {
    min-height: 150px;
    transition: all 0.3s ease;
}

